/* Expand/collapse the full repr generated by autoall's constant-value block. */
(() => {
  const open = (root) => {
    const summary = root.querySelector(".constant-value-summary");
    const full = root.querySelector(".constant-value-full");
    if (summary && full) {
      summary.hidden = true;
      full.hidden = false;
    }
  };

  const close = (root) => {
    const summary = root.querySelector(".constant-value-summary");
    const full = root.querySelector(".constant-value-full");
    if (summary && full) {
      summary.hidden = false;
      full.hidden = true;
    }
  };

  document.addEventListener("click", (event) => {
    const toggle = event.target.closest(".constant-value-toggle");
    if (toggle) {
      open(toggle.closest(".constant-value"));
      return;
    }
    const closeButton = event.target.closest(".constant-value-close");
    if (closeButton) {
      close(closeButton.closest(".constant-value"));
    }
  });
})();
